BEGIN;

-- Channels (39)
ON CONFLICT (sno) DO UPDATE SET name = EXCLUDED.name, channel_name = EXCLUDED.channel_name, handle = EXCLUDED.handle,
  category = EXCLUDED.category, group_name = EXCLUDED.group_name, youtube_url = EXCLUDED.youtube_url,
  viral_score = EXCLUDED.viral_score, score = EXCLUDED.score, cpm_tier = EXCLUDED.cpm_tier,
  team_size = EXCLUDED.team_size, status = EXCLUDED.status;

-- Playlists (187)
DELETE FROM playlists WHERE channel_sno IN ('1.01', '1.02', '1.03', '1.04', '1.05', '1.06', '1.07', '1.08', '1.09', '1.10', '1.11', '1.12', '1.13', '1.14', '1.15', '1.16', '1.17', '1.18', '1.19', '1.20', '1.21', '1.22', '1.23', '1.24', '1.25', '1.26', '1.27', '1.28', '1.29', '1.30', '1.31', '1.32', '1.33', '1.34', '1.35', '1.36', '1.37', '1.38', '1.39');
ON CONFLICT (channel_sno, playlist_name) DO NOTHING;

-- Social accounts (36)
DELETE FROM social_links;

-- Websites (29 live + 3 in progress)
DELETE FROM websites;

-- Home page planets + contact email (edit later in Admin -> Home Page)
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

-- Profile (About Me) so BigQuery and future pages can use it
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

COMMIT;
