INSERT INTO site_settings (key, value) VALUES ('profile', '{"name":"Pujith Chowdary Sakhamuri","short":"Pujith Sakhamuri","headline":"Full Stack Data & AI Engineer | GCP · BigQuery · Dataflow · Vertex AI · Gemini API | Network Data Analyst @ Telka (T-Mobile) | Pujiverse Creator","tagline":"Full Stack Data & AI Engineer · Network Data Analyst · Pujiverse Creator","location":"Celina, Texas, United States","email":"pujiverse@gmail.com","officialChannel":{"name":"Pujith Sakhamuri","handle":"@PujithSakhamuri","url":"https://www.youtube.com/@PujithSakhamuri"},"links":{"home":"https://pujiverse.github.io/Pujiverse-Network/","portfolio":"https://pujith-sakhamuri-portfolio.vercel.app/","github":"https://github.com/pujiverse","resume":"https://github.com/pujiverse/pujiverse/blob/main/resume.pdf","linkedin":"https://www.linkedin.com/in/pujith-sakhamuri-06b69a137/"},"about":"I build data platforms and AI tools, from pipelines and semantic models on Google Cloud to web apps people use. Network Data Analyst at Telka supporting T-Mobile; previously Full Stack Data & AI Engineer for CVS Pharmacy (SR Systems) and Data Engineer for Cleveland Clinic (IvyNova). Creator of Pujiverse: 39 YouTube channels plus interactive projects like The AI Timeline, Vehicle Universe and the Pujiverse World Atlas.","stats":{"projects":32,"live":29,"githubPages":11,"vercel":18,"aiStudio":19,"channels":39,"platforms":37,"experience":8},"experience":[{"company":"Pujiverse Network","title":"Creator & Founder","type":"Self-employed","location":"Remote","start":"Mar 2025","end":"Present","text":"Built and run a network of 39 YouTube channels, interactive data projects (The AI Timeline, Vehicle Universe, World Atlas) and 18+ Gemini-powered apps.","link":"https://pujiverse.github.io/Pujiverse-Network/"},{"company":"Telka LLC","title":"Network Data Analyst","type":"Full-time","location":"Prosper, TX (client: T-Mobile, Central Region)","start":"Aug 2026","end":"Present","text":"5G/LTE drive-test data and RF metrics (RSRP, RSRQ, SINR, throughput); Python/SQL log validation; FCC compliance audits; weekly KPI dashboards."},{"company":"Alignerr","title":"AI & LLM Evaluation Specialist","type":"Contract","location":"Remote","start":"Jan 2025","end":"Present","text":"Evaluate LLM outputs on Python, SQL and multi-step reasoning under RLHF guidelines; build tool-calling validation datasets."},{"company":"Upwork","title":"Full Stack & Generative AI Developer","type":"Freelance","location":"Remote","start":"Jan 2024","end":"Present","text":"Web apps and AI tools for small businesses with React, TypeScript, Python and the Gemini API on Vercel and Cloud Run."},{"company":"SR Systems LLC","title":"Full Stack Data & AI Engineer","type":"Full-time","location":"Texas (client: CVS Pharmacy)","start":"Jul 2024","end":"Jul 2026","text":"BigQuery semantic models for Vertex AI; Dataflow, Pub/Sub, Cloud Composer pipelines; Cloud Run APIs; Terraform and GitHub Actions; HIPAA data governance."},{"company":"Ivynova Solutions, Inc.","title":"Data Engineer","type":"Full-time","location":"Cleveland, OH (client: Cleveland Clinic)","start":"Jun 2023","end":"Jul 2024","text":"GCS ingestion of clinical feeds; Cloud Functions and Airflow DAGs (99.8% data accuracy); star-schema models in BigQuery for BI."},{"company":"Cleveland State University","title":"Graduate Assistant, Data Analytics & Infrastructure Support","type":"Part-time","location":"Cleveland, OH","start":"Mar 2022","end":"May 2023","text":"SQL reporting datasets, automated ETL workflows, Power BI and Tableau dashboards, data validation checks."},{"company":"Self-employed","title":"Freelance Developer / Data Analyst","type":"Freelance","location":"Hyderabad, India","start":"Oct 2020","end":"Jan 2022","text":"Mentored engineering students on academic projects; built web applications; debugging and project documentation."}],"education":[{"school":"Indiana Wesleyan University","degree":"Master of Science","field":"Artificial Intelligence & Machine Learning","start":"Jul 2026","end":"Dec 2027 (expected)","notes":"Coursework: AIML-500 Machine Learning Fundamentals, DTAN-500 Foundations of Data Analytics, DTAN-505 Data Visualization (R)"},{"school":"Cleveland State University","degree":"Master of Science","field":"Computer and Information Sciences","start":"Jan 2022","end":"May 2023","notes":"Graduate Assistant, Data Analytics & Infrastructure Support"},{"school":"JNTUH","degree":"Bachelor of Technology","field":"Computer Science and Engineering","start":"2016","end":"2020","notes":""}],"skills":[{"area":"Cloud & Data Platform","items":"Google Cloud Platform (GCP), Google BigQuery, Vertex AI, Cloud Dataflow, Pub/Sub, Cloud Composer, Apache Airflow, Cloud Run, Cloud Functions, Cloud Storage"},{"area":"AI & Machine Learning","items":"Generative AI, Gemini API, Large Language Models, AI Agents, Google ADK, Prompt Engineering, Machine Learning, RLHF evaluation"},{"area":"Data Engineering & Analytics","items":"Data Engineering, Data Modeling, Dimensional Modeling, Semantic Modeling, ETL, Data Pipelines, Data Governance, Data Quality, HIPAA Compliance, KPI Analysis, RF Analytics (5G/LTE)"},{"area":"Programming","items":"Python, SQL, PySpark, R, TypeScript, JavaScript, HTML, CSS"},{"area":"Web & App Development","items":"React, FastAPI, REST APIs, Firebase, Supabase, PostgreSQL, MySQL, Vercel, GitHub Pages"},{"area":"DevOps","items":"Terraform, Docker, GitHub Actions, CI/CD, Git, Linux"},{"area":"BI & Visualization","items":"Power BI, Tableau, Data Visualization, Dashboard Design"},{"area":"Creative","items":"Content Creation, Video Production, YouTube, Brand Identity, Web Design, UI/UX Design"}]}'::jsonb)
